import numpy as np
import matplotlib.pyplot as plt
from scipy.stats import norm

def task_func(n_samples=1000, mu=0, sigma=1, random_seed=0):
    if isinstance(n_samples, bool):
        raise ValueError("n_samples must be a positive integer.")
    try:
        n_samples_int = int(n_samples)
    except (TypeError, ValueError, OverflowError):
        raise ValueError("n_samples must be a positive integer.")
    if n_samples_int != n_samples or n_samples_int <= 0:
        raise ValueError("n_samples must be a positive integer.")

    if not np.isscalar(mu) or not np.isfinite(mu):
        raise ValueError("mu must be finite.")
    if not np.isscalar(sigma) or not np.isfinite(sigma) or sigma <= 0:
        raise ValueError("sigma must be a positive finite number.")

    np.random.seed(random_seed)
    samples = np.random.normal(loc=mu, scale=sigma, size=n_samples_int)

    fig, ax = plt.subplots()
    ax.hist(samples, density=True)

    x = np.linspace(mu - 4 * sigma, mu + 4 * sigma, 1000)
    ax.plot(x, norm.pdf(x, loc=mu, scale=sigma), color="red", linewidth=2)

    return ax, samples
